code='''from collections import deque
def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); out=[r[:] for r in grid]
    for y in range(h):
      for x in range(w):
        if grid[y][x]==0 or (y,x) in seen: continue
        q=[(y,x)]; seen.add((y,x)); comp=[]
        while q:
          a,b=q.pop(); comp.append((a,b))
          for na,nb in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
            if 0<=na<h and 0<=nb<w and grid[na][nb]!=0 and (na,nb) not in seen:
              seen.add((na,nb)); q.append((na,nb))
        colors=set(grid[a][b] for a,b in comp)
        # Nested bands are ordered by their bounding-box area, outer to inner.
        ranks=[]
        for c in colors:
          pts=[(a,b) for a,b in comp if grid[a][b]==c]
          ys=[p[0] for p in pts]; xs=[p[1] for p in pts]
          ranks.append(( (max(ys)-min(ys)+1)*(max(xs)-min(xs)+1), c))
        ordered=[c for _,c in sorted(ranks,reverse=True)]
        mapping={ordered[i]:ordered[-1-i] for i in range(len(ordered))}
        for a,b in comp: out[a][b]=mapping[grid[a][b]]
    return out
'''
